const state = { user: null, tasks: [], users: [], files: [], dashboard: null, notifications: { messages: 0, tasks: 0 } };
const app = document.querySelector('#app');
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
let currentTheme = localStorage.getItem('haitani-theme') || 'ran';
let notificationTimer;
document.documentElement.dataset.theme = currentTheme;
let ganttZoom = 'day';
let ganttGroupBy = 'none';
let ganttStatusFilter = '';
let ganttAssigneeFilter = '';
const ganttCollapsedGroups = new Set();
const GANTT_ZOOM = { day: { colWidth: 56, labelEvery: 1, format: d => d.toLocaleDateString('es', { day: '2-digit', month: 'short' }) }, week: { colWidth: 26, labelEvery: 7, format: d => `Sem ${d.toLocaleDateString('es', { day: '2-digit', month: 'short' })}` }, month: { colWidth: 10, labelEvery: 'month', format: d => d.toLocaleDateString('es', { month: 'short', year: '2-digit' }) } };
function addDays(dateStr, delta) { const base = dateStr || new Date().toISOString().slice(0, 10); const date = new Date(`${base}T00:00:00`); date.setDate(date.getDate() + delta); return date.toISOString().slice(0, 10) }
function themeToggle(){return `<div class="theme-switch" role="group" aria-label="Tema visual"><button class="theme-option ${currentTheme==='ran'?'active':''}" data-theme="ran">蘭</button><button class="theme-option ${currentTheme==='ryutan'?'active':''}" data-theme="ryutan">竜 胆</button></div>`}
function bindTheme(){document.querySelectorAll('[data-theme]').forEach(button=>button.onclick=()=>{currentTheme=button.dataset.theme;localStorage.setItem('haitani-theme',currentTheme);document.documentElement.dataset.theme=currentTheme;document.querySelectorAll('.theme-option').forEach(option=>option.classList.toggle('active',option.dataset.theme===currentTheme))})}
async function api(url, options = {}) { const response = await fetch(`/api${url}`, { credentials:'same-origin', ...options }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'No fue posible completar la operación.'); return data; }
function notificationDot(type){return `<i class="notification-dot" data-type="${type}" ${state.notifications[type]?'':'hidden'} title="${state.notifications[type]||0} notificaciones nuevas"></i>`}
async function refreshNotifications(){if(!state.user)return;try{state.notifications=await api('/notifications');document.querySelectorAll('.notification-dot').forEach(dot=>{const count=state.notifications[dot.dataset.type]||0;dot.hidden=!count;dot.title=`${count} notificaciones`})}catch{} }
function startNotificationPolling(){clearInterval(notificationTimer);notificationTimer=setInterval(refreshNotifications,30000)}
function notify(message) { const node = document.createElement('div'); node.className='toast'; node.textContent=message; document.body.append(node); setTimeout(() => node.remove(), 3000); }
function loginView(error='') { app.innerHTML=`<main class="login"><form class="login-box" id="login-form"><div class="brand">HAI<span>TANI</span></div><div class="eyebrow">Centro de control</div><h1>Sakura Coffee</h1><p class="muted">Organiza el trabajo del equipo con una vista clara del proyecto.</p>${error?`<div class="alert">${esc(error)}</div>`:''}<label>Usuario o correo<input class="input" name="username" required autofocus></label><label>Contraseña<input class="input" name="password" type="password" required></label><button class="btn" style="width:100%;margin-top:22px">Iniciar sesión</button></form></main>`; document.querySelector('#login-form').onsubmit=async event=>{event.preventDefault();try{const data=await api('/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.user=data.user;location.hash=data.redirect;render()}catch(error){loginView(error.message)}}}
function sidebar(){const admin=state.user.role==='admin';const links=admin?[['/admin/dashboard','Dashboard'],['/admin/tasks','Tareas','tasks'],['/admin/kanban','Kanban'],['/admin/gantt','Gantt'],['/admin/members','Integrantes'],['/admin/files','Archivos'],['/admin/messages','Mensajes','messages'],['/admin/github','GitHub'],['/admin/github/commits','Commits'],['/admin/team-activity','Actividad del equipo'],['/admin/settings/github','Configuración']]:[['/member/dashboard','Dashboard'],['/member/tasks','Mis tareas','tasks'],['/member/files','Archivos'],['/member/members','Equipo'],['/member/messages','Mensajes','messages'],['/member/github','GitHub'],['/member/profile','Perfil']];return `<aside class="side" id="side"><div class="brand">HAI<span>TANI</span></div><div class="project">Sakura Coffee</div><div class="nav-title">Workspace</div>${links.map(([href,label,type])=>`<button class="nav ${location.hash===href?'active':''}" data-route="${href}">${label}${type?notificationDot(type):''}</button>`).join('')}<div class="nav-title">Cuenta</div><button class="nav" id="logout">Cerrar sesión</button></aside>`}
function avatarMarkup(user,size='avatar'){return user.profile_photo?`<img class="${size}" src="${esc(user.profile_photo)}" alt="Foto de ${esc(user.name)}">`:`<span class="${size}">${esc(user.name?.[0]||'?')}</span>`}
function layout(content){app.innerHTML=`<div class="shell">${sidebar()}<section class="main"><header class="topbar"><button class="mobile-toggle" id="menu">☰</button><span class="muted">${state.user.role==='admin'?'Panel administrativo':'Espacio personal'}</span><div class="topbar-actions">${themeToggle()}<div class="user-chip"><span>${esc(state.user.name)}</span>${avatarMarkup(state.user)}</div></div></header><main class="content">${content}</main></section></div>`;document.querySelectorAll('[data-route]').forEach(node=>node.onclick=()=>{location.hash=node.dataset.route;render()});document.querySelector('#logout').onclick=async()=>{await api('/auth/logout',{method:'POST'});state.user=null;location.hash='';loginView()};document.querySelector('#menu').onclick=()=>document.querySelector('#side').classList.toggle('open');bindTheme()}
function heading(title, subtitle, action=''){return `<div class="heading"><div><div class="eyebrow">Haitani / Sakura Coffee</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
async function dashboard(){state.dashboard=await api('/dashboard');const s=state.dashboard.stats;let githubStatus='<div class="alert">Comprobando conexión con GitHub...</div>';try{const github=await api('/github/repository');if(!github.configured){githubStatus='<div class="alert">GitHub aún no está configurado.</div>'}else if(github.error){githubStatus=`<div class="alert">${esc(github.error)}</div>`}else{githubStatus=`<div class="alert"><strong>GitHub conectado</strong><br>${esc(github.data.full_name||'Repositorio configurado')} · Rama principal: ${esc(github.data.default_branch||'No disponible')}</div>`}}catch(error){githubStatus='<div class="alert">No fue posible consultar GitHub en este momento.</div>'}return `${heading(`Hola, ${esc(state.user.name)}`,'Vista general de tu actividad y del proyecto.')}<div class="grid stats"><div class="card stat"><div class="label">${state.user.role==='admin'?'Integrantes':'Mis tareas'}</div><div class="num pink">${state.user.role==='admin'?s.members:s.totalTasks}</div></div><div class="card stat"><div class="label">Pendientes</div><div class="num yellow">${s.byStatus.find(x=>x.status==='pendiente')?.count||0}</div></div><div class="card stat"><div class="label">En proceso</div><div class="num lilac">${s.byStatus.find(x=>x.status==='en_proceso')?.count||0}</div></div><div class="card stat"><div class="label">Completadas</div><div class="num green">${s.completed}</div></div><div class="card stat"><div class="label">Progreso</div><div class="num">${s.progress}%</div><div class="bar"><i style="width:${s.progress}%"></i></div></div></div><div class="grid two" style="margin-top:16px"><section class="card"><h2>Próximas tareas</h2><div id="dashboard-tasks" class="empty">Cargando tareas...</div></section><section class="card"><h2>Proyecto</h2><p class="muted">${esc(state.dashboard.project.description)}</p>${githubStatus}</section></div>`}
async function renderDashboard(){const content=await dashboard();layout(content);const tasks=await api('/tasks');document.querySelector('#dashboard-tasks').innerHTML=tasks.slice(0,5).map(taskRow).join('')||'<div class="empty">No hay tareas asignadas.</div>'}
function taskRow(task){return `<div style="display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid var(--line)"><span>${esc(task.title)}<small class="muted" style="display:block">${esc(task.assignee_name||'Sin asignar')}</small></span><span class="badge ${task.status==='completada'?'green':task.status==='en_proceso'?'pink':'yellow'}">${task.status.replace('_',' ')}</span></div>`}
async function tasksView(){const tasks=await api('/tasks');const users=state.user.role==='admin'?await api('/users'):[];return `${heading(state.user.role==='admin'?'Tareas':'Mis tareas','Trabajo almacenado en PostgreSQL.',state.user.role==='admin'?'<button class="btn" id="new-task">Nueva tarea</button>':'')}<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Tarea</th><th>Responsable</th><th>Prioridad</th><th>Estado</th><th>Fecha límite</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${esc(t.title)}<small class="muted" style="display:block">${esc(t.description)}</small></td><td>${esc(t.assignee_name||'Sin asignar')}</td><td><span class="badge ${t.priority==='alta'?'pink':''}">${t.priority}</span></td><td><select class="select status-select" data-id="${t.id}"><option value="pendiente" ${t.status==='pendiente'?'selected':''}>Pendiente</option><option value="en_proceso" ${t.status==='en_proceso'?'selected':''}>En proceso</option><option value="completada" ${t.status==='completada'?'selected':''}>Completada</option></select></td><td>${esc(t.due_date||'No definida')}</td><td>${state.user.role==='admin'?`<button class="btn secondary edit-task" data-id="${t.id}">Editar</button> <button class="btn danger delete-task" data-id="${t.id}">Eliminar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay tareas.</td></tr>'}</tbody></table></div></section>${state.user.role==='admin'?taskForm(users):''}`}
function taskForm(users){return `<section class="card" id="task-form" style="display:none;margin-top:16px"><h2 id="task-form-title">Nueva tarea</h2><form class="form-grid"><input type="hidden" name="id"><label>Título<input class="input" name="title" required></label><label>Responsable<select class="select" name="assigned_to"><option value="">Sin asignar</option>${users.filter(u=>u.role==='member').map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label>Prioridad<select class="select" name="priority"><option>baja</option><option selected>media</option><option>alta</option></select></label><label>Estado<select class="select" name="status"><option>pendiente</option><option>en_proceso</option><option>completada</option></select></label><label>Fecha inicial<input class="input" name="start_date" type="date"></label><label>Fecha límite<input class="input" name="due_date" type="date"></label><label class="full">Descripción<textarea class="textarea" name="description"></textarea></label><div class="actions full"><button class="btn">Guardar tarea</button><button type="button" class="btn secondary" id="cancel-task">Cancelar</button></div></form></section>`}
async function renderTasks(){layout(await tasksView());const formSection=document.querySelector('#task-form');const form=document.querySelector('#task-form form');const openForm=task=>{form.reset();formSection.style.display='block';document.querySelector('#task-form-title').textContent=task?'Editar tarea':'Nueva tarea';form.elements.id.value=task?.id||'';form.elements.title.value=task?.title||'';form.elements.description.value=task?.description||'';form.elements.assigned_to.value=task?.assigned_to||'';form.elements.priority.value=task?.priority||'media';form.elements.status.value=task?.status||'pendiente';form.elements.start_date.value=task?.start_date||'';form.elements.due_date.value=task?.due_date||''};document.querySelector('#new-task')?.addEventListener('click',()=>openForm());document.querySelector('#cancel-task')?.addEventListener('click',()=>formSection.style.display='none');document.querySelector('#task-form form')?.addEventListener('submit',async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const id=values.id;delete values.id;try{await api(id?`/tasks/${id}`:'/tasks',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});notify(id?'Tarea actualizada':'Tarea creada');renderTasks()}catch(error){notify(error.message)}});document.querySelectorAll('.edit-task').forEach(button=>button.onclick=async()=>{try{openForm(await api(`/tasks/${button.dataset.id}`))}catch(error){notify(error.message)}});document.querySelectorAll('.status-select').forEach(select=>select.onchange=async()=>{try{await api(`/tasks/${select.dataset.id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});notify('Estado actualizado')}catch(error){notify(error.message)}});document.querySelectorAll('.delete-task').forEach(button=>button.onclick=async()=>{if(confirm('¿Eliminar tarea?')){await api(`/tasks/${button.dataset.id}`,{method:'DELETE'});renderTasks()}})}
async function kanban(){const tasks=await api('/tasks');return `${heading('Kanban','Arrastra las tareas para actualizar su estado.') }<div class="kanban">${[['pendiente','Pendiente'],['en_proceso','En proceso'],['completada','Completada']].map(([status,label])=>`<section class="column" data-status="${status}"><h3>${label.toUpperCase()}</h3>${tasks.filter(t=>t.status===status).map(t=>`<article class="task-card" draggable="true" data-id="${t.id}"><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="meta"><span>${esc(t.assignee_name||'Sin asignar')}</span><span>${esc(t.due_date||'')}</span></div></article>`).join('')}</section>`).join('')}</div>`}
async function renderKanban(){layout(await kanban());document.querySelectorAll('.task-card').forEach(card=>card.ondragstart=e=>e.dataTransfer.setData('id',card.dataset.id));document.querySelectorAll('.column').forEach(column=>{column.ondragover=e=>e.preventDefault();column.ondrop=async e=>{await api(`/tasks/${e.dataTransfer.getData('id')}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:column.dataset.status})});renderKanban()}})}
async function filesView(){const files=await api('/files');return `${heading('Archivos','Documentos compartidos y evidencias del equipo.','<form id="upload-form" class="actions"><input class="input" type="file" name="file" required><button class="btn">Subir evidencia</button></form>')}<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Archivo</th><th>Tipo</th><th>Tamaño</th><th>Subido por</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>${files.map(f=>`<tr><td>${esc(f.original_name)}</td><td>${esc(f.mime_type)}</td><td>${Math.ceil(f.size/1024)} KB</td><td>${esc(f.uploader_name)}</td><td>${esc(f.created_at)}</td><td><button class="btn secondary view-file" data-id="${f.id}" data-name="${esc(f.original_name)}" data-type="${esc(f.mime_type)}">Visualizar</button> <a class="btn secondary" href="/api/files/${f.id}/download">Descargar</a>${state.user.role==='admin'?` <button class="btn danger delete-file" data-id="${f.id}">Eliminar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Aún no hay archivos compartidos.</td></tr>'}</tbody></table></div></section><div id="file-viewer" class="file-viewer" hidden><div class="file-viewer-panel"><div class="file-viewer-head"><strong id="file-viewer-title"></strong><button class="btn secondary" id="close-file-viewer">Cerrar</button></div><div id="file-viewer-content" class="file-viewer-content"></div></div></div>`}
async function renderFiles(){layout(await filesView());document.querySelector('#upload-form')?.addEventListener('submit',async e=>{e.preventDefault();await api('/files',{method:'POST',body:new FormData(e.target)});notify('Archivo subido');renderFiles()});document.querySelectorAll('.view-file').forEach(button=>button.onclick=()=>{const viewer=document.querySelector('#file-viewer');const type=button.dataset.type;const url=`/api/files/${button.dataset.id}/view`;document.querySelector('#file-viewer-title').textContent=button.dataset.name;document.querySelector('#file-viewer-content').innerHTML=type.startsWith('image/')?`<img class="file-preview-image" src="${url}" alt="${esc(button.dataset.name)}">`:`<iframe class="file-preview-frame" src="${url}" title="${esc(button.dataset.name)}"></iframe>`;viewer.hidden=false});document.querySelector('#close-file-viewer')?.addEventListener('click',()=>{document.querySelector('#file-viewer').hidden=true;document.querySelector('#file-viewer-content').innerHTML=''});document.querySelectorAll('.delete-file').forEach(b=>b.onclick=async()=>{await api(`/files/${b.dataset.id}`,{method:'DELETE'});renderFiles()})}
async function githubView(section='repository'){const data=await api(`/github/${section==='pulls'?'pull-requests':section}`);let body='';if(!data.configured)body='<div class="empty">GitHub aún no está configurado.</div>';else if(data.error)body=`<div class="alert">${esc(data.error)}</div>`;else if(section==='repository'){const r=data.data;body=`<div class="grid stats"><div class="card stat"><div class="label">Nombre</div><div class="num">${esc(r.name)}</div></div><div class="card stat"><div class="label">Lenguaje</div><div class="num lilac">${esc(r.language||'No disponible')}</div></div><div class="card stat"><div class="label">Estrellas</div><div class="num yellow">${r.stargazers_count}</div></div><div class="card stat"><div class="label">Última actualización</div><div class="num" style="font-size:17px">${new Date(r.updated_at).toLocaleDateString('es')}</div></div></div><section class="card" style="margin-top:16px"><h2>${esc(r.full_name)}</h2><p class="muted">${esc(r.description||'No disponible')}</p><a class="btn" href="${esc(r.html_url)}" target="_blank">Abrir en GitHub</a></section>`}else if(section==='commits'){body=`<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Commit</th><th>Autor</th><th>Usuario GitHub</th><th>SHA</th><th>Fecha</th><th></th></tr></thead><tbody>${data.data.map(commit=>`<tr><td>${esc(commit.message)}</td><td>${esc(commit.author)}</td><td>${esc(commit.github_username||'No disponible')}</td><td><code>${esc(commit.sha)}</code></td><td>${esc(commit.date||'No disponible')}</td><td><a class="btn secondary" href="${esc(commit.url)}" target="_blank">Ver commit</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay commits disponibles.</td></tr>'}</tbody></table></div></section>`}else{const rows=data.data;body=`<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Actividad</th><th>Usuario</th><th>Fecha</th><th></th></tr></thead><tbody>${rows.map(item=>`<tr><td>${esc(item.message||item.title||item.action||item.name)}</td><td>${esc(item.github_username||item.author||item.user||'No disponible')}</td><td>${esc(item.date||item.updated||'No disponible')}</td><td>${item.url?`<a class="btn secondary" href="${esc(item.url)}" target="_blank">Ver en GitHub</a>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}return `${heading(section==='commits'?'Commits':'GitHub','Información real del repositorio privado de Sakura Coffee.')}<div class="actions" style="margin-bottom:16px"><button class="btn secondary" data-gh="repository">Overview</button><button class="btn secondary" data-gh="commits">Commits</button><button class="btn secondary" data-gh="pulls">Pull Requests</button><button class="btn secondary" data-gh="branches">Branches</button><button class="btn secondary" data-gh="activity">Activity</button></div>${body}`}
async function renderGithub(section='repository'){layout(await githubView(section));document.querySelectorAll('[data-gh]').forEach(b=>b.onclick=()=>renderGithub(b.dataset.gh))}
function profile(){const photo=state.user.profile_photo?`<img class="profile-photo" src="${esc(state.user.profile_photo)}" alt="Foto de perfil">`:`<div class="profile-photo profile-placeholder">${esc(state.user.name[0])}</div>`;return `${heading('Mi perfil','Información de tu cuenta en Haitani.')}<section class="card profile-card"><div class="profile-summary">${photo}<div><h2>${esc(state.user.name)}</h2><p class="muted">${esc(state.user.email)}</p></div></div><div class="grid stats"><div><div class="muted">Usuario</div><h2>${esc(state.user.username)}</h2></div><div><div class="muted">GitHub</div><h2>${esc(state.user.github_username||'GitHub no configurado')}</h2></div></div></section><section class="card"><h2>Actualizar perfil</h2><p class="muted">Cambia tu foto o actualiza tu contraseña.</p><form id="profile-form" class="form-grid" enctype="multipart/form-data"><label>Foto de perfil<input class="input" name="photo" type="file" accept=".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp"></label><label>Contraseña actual<input class="input" name="current_password" type="password" autocomplete="current-password"></label><label>Nueva contraseña<input class="input" name="new_password" type="password" minlength="8" autocomplete="new-password"></label><div class="actions full"><button class="btn">Guardar cambios</button></div></form></section>`}
async function renderProfile(){layout(profile());document.querySelector('#profile-form').onsubmit=async event=>{event.preventDefault();try{const data=await api('/users/me/profile',{method:'PUT',body:new FormData(event.target)});state.user.profile_photo=data.profile_photo;notify('Perfil actualizado');renderProfile()}catch(error){notify(error.message)}}}
async function members(){const users=await api('/users');return `${heading('Integrantes','Personas activas en el equipo.','<button class="btn" id="new-member">Nuevo integrante</button>')}<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Foto</th><th>Nombre</th><th>Usuario</th><th>Correo</th><th>GitHub</th><th>Estado</th><th></th></tr></thead><tbody>${users.filter(u=>u.role==='member').map(u=>`<tr><td>${u.profile_photo?`<img class="avatar" src="${esc(u.profile_photo)}" alt="Foto de ${esc(u.name)}">`:`<span class="avatar">${esc(u.name[0])}</span>`}</td><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.email)}</td><td>${esc(u.github_username||'No configurado')}</td><td>${u.active?'Activo':'Inactivo'}</td><td><button class="btn secondary edit-user" data-user="${encodeURIComponent(JSON.stringify(u))}">Editar</button> <button class="btn secondary toggle-user" data-id="${u.id}" data-active="${u.active}">${u.active?'Desactivar':'Activar'}</button> <button class="btn danger delete-user" data-id="${u.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></section><section class="card" id="member-form" style="display:none;margin-top:16px"><h2 id="member-form-title">Nuevo integrante</h2><form class="form-grid"><input type="hidden" name="id"><label>Nombre<input class="input" name="name" required></label><label>Usuario<input class="input" name="username" required></label><label>Correo<input class="input" name="email" type="email" required></label><label>Contraseña<input class="input" name="password" placeholder="Déjala vacía para conservarla"></label><label>GitHub username<input class="input" name="github_username"></label><label>Estado<select class="select" name="active"><option value="1">Activo</option><option value="0">Inactivo</option></select></label><div class="actions full"><button class="btn">Guardar</button><button class="btn secondary" type="button" id="cancel-member">Cancelar</button></div></form></section>`}
async function renderMembers(){layout(await members());const formSection=document.querySelector('#member-form');const form=document.querySelector('#member-form form');const openForm=(user=null)=>{form.reset();formSection.style.display='block';document.querySelector('#member-form-title').textContent=user?'Editar integrante':'Nuevo integrante';form.elements.id.value=user?.id||'';form.elements.name.value=user?.name||'';form.elements.username.value=user?.username||'';form.elements.email.value=user?.email||'';form.elements.github_username.value=user?.github_username||'';form.elements.active.value=user?.active?'1':'0';form.elements.password.value='';form.elements.password.required=!user};document.querySelector('#new-member').onclick=()=>openForm();document.querySelector('#cancel-member').onclick=()=>formSection.style.display='none';form.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));const id=values.id;delete values.id;if(!values.password)delete values.password;try{await api(id?`/users/${id}`:'/users',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});notify(id?'Integrante actualizado':'Integrante creado');renderMembers()}catch(error){notify(error.message)}};document.querySelectorAll('.edit-user').forEach(button=>button.onclick=()=>openForm(JSON.parse(decodeURIComponent(button.dataset.user))));document.querySelectorAll('.toggle-user').forEach(b=>b.onclick=async()=>{try{await api(`/users/${b.dataset.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:b.dataset.active==='0'})});renderMembers()}catch(error){notify(error.message)}});document.querySelectorAll('.delete-user').forEach(b=>b.onclick=async()=>{if(confirm('¿Eliminar integrante?')){await api(`/users/${b.dataset.id}`,{method:'DELETE'});renderMembers()}})}
async function team(){const users=(await api('/users')).filter(user=>user.active);return `${heading('Equipo','Conoce a las personas del equipo y sus fotos de perfil.')}<section class="team-grid">${users.map(user=>`<article class="card team-card">${avatarMarkup(user,'team-avatar')}<div><h2>${esc(user.name)}</h2><p class="muted">@${esc(user.username)}</p><p>${esc(user.email)}</p></div><button class="btn secondary message-user" data-id="${user.id}">Enviar mensaje</button></article>`).join('')}</section>`}
async function renderTeam(){layout(await team());document.querySelectorAll('.message-user').forEach(button=>button.onclick=()=>{location.hash=`#/${state.user.role}/messages?user=${button.dataset.id}`;renderMessages()})}
const callState={socket:null,peer:null,stream:null,remoteStream:null,peerId:null,callId:null,muted:false};
function signalSocket(){if(callState.socket?.readyState===WebSocket.OPEN)return callState.socket;const protocol=location.protocol==='https:'?'wss':'ws';callState.socket=new WebSocket(`${protocol}://${location.host}`);callState.socket.onopen=()=>callState.socket.send(JSON.stringify({type:'register',userId:state.user.id}));callState.socket.onmessage=event=>handleCallSignal(JSON.parse(event.data));return callState.socket}
function sendSignal(message){const socket=signalSocket();const send=()=>socket.send(JSON.stringify(message));if(socket.readyState===WebSocket.OPEN)send();else socket.addEventListener('open',send,{once:true})}
async function startCall(peerId,video){try{callState.peerId=Number(peerId);const call=await api('/calls',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({receiver_id:callState.peerId,call_type:video?'video':'audio'})});callState.callId=call.id;callState.stream=await navigator.mediaDevices.getUserMedia({audio:true,video});callState.peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});callState.remoteStream=new MediaStream();document.querySelector('#call-remote').srcObject=callState.remoteStream;document.querySelector('#call-local').srcObject=callState.stream;callState.stream.getTracks().forEach(track=>callState.peer.addTrack(track,callState.stream));callState.peer.ontrack=event=>event.streams[0].getTracks().forEach(track=>callState.remoteStream.addTrack(track));callState.peer.onicecandidate=event=>event.candidate&&sendSignal({type:'ice',to:callState.peerId,candidate:event.candidate});document.querySelector('#call-modal').hidden=false;const offer=await callState.peer.createOffer();await callState.peer.setLocalDescription(offer);sendSignal({type:'offer',to:callState.peerId,offer,video,callId:callState.callId})}catch(error){notify('No fue posible iniciar la llamada. Revisa los permisos de cámara y micrófono.');endCall()}}
async function handleCallSignal(message){if(message.type==='offer'){if(callState.peer)endCall();callState.peerId=message.from;callState.callId=message.callId;callState.stream=await navigator.mediaDevices.getUserMedia({audio:true,video:message.video});callState.peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});callState.remoteStream=new MediaStream();document.querySelector('#call-remote').srcObject=callState.remoteStream;document.querySelector('#call-local').srcObject=callState.stream;callState.stream.getTracks().forEach(track=>callState.peer.addTrack(track,callState.stream));callState.peer.ontrack=event=>event.streams[0].getTracks().forEach(track=>callState.remoteStream.addTrack(track));callState.peer.onicecandidate=event=>event.candidate&&sendSignal({type:'ice',to:callState.peerId,candidate:event.candidate});await callState.peer.setRemoteDescription(message.offer);const answer=await callState.peer.createAnswer();await callState.peer.setLocalDescription(answer);document.querySelector('#call-modal').hidden=false;await api(`/calls/${callState.callId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'answered'})});sendSignal({type:'answer',to:callState.peerId,answer})}else if(message.type==='answer'&&callState.peer){await callState.peer.setRemoteDescription(message.answer);if(callState.callId)await api(`/calls/${callState.callId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'answered'})})}else if(message.type==='ice'&&callState.peer)await callState.peer.addIceCandidate(message.candidate)}
function toggleMute(){callState.muted=!callState.muted;callState.stream?.getAudioTracks().forEach(track=>{track.enabled=!callState.muted});const button=document.querySelector('#mute-call');if(button)button.textContent=callState.muted?'Activar micrófono':'Silenciar micrófono'}
function endCall(){callState.peer?.close();callState.stream?.getTracks().forEach(track=>track.stop());callState.peer=null;callState.stream=null;callState.remoteStream=null;callState.peerId=null;callState.callId=null;callState.muted=false;const modal=document.querySelector('#call-modal');if(modal)modal.hidden=true}
function chatBackground(key){return localStorage.getItem(`haitani-chat-bg-${key}`)||'linear-gradient(135deg,#13202B,#2A3541)'}
async function messagesView(selectedId){const users=(await api('/users')).filter(user=>user.active&&user.id!==state.user.id);const selected=users.find(user=>String(user.id)===String(selectedId))||users[0];const messages=selected?await api(`/messages?user_id=${selected.id}`):[];const conversationKey=selected?`${Math.min(state.user.id,selected.id)}-${Math.max(state.user.id,selected.id)}`:'';return `${heading('Mensajes','Conversaciones directas con las personas del equipo.')}<section class="messages-layout"><aside class="card conversation-list">${users.map(user=>`<button class="conversation-user ${selected&&user.id===selected.id?'active':''}" data-id="${user.id}">${avatarMarkup(user,'message-avatar')}<span><strong>${esc(user.name)}</strong><small>@${esc(user.username)}</small></span></button>`).join('')||'<div class="empty">No hay otros usuarios activos.</div>'}</aside><section class="card conversation"><div class="conversation-header">${selected?`${avatarMarkup(selected,'message-avatar')}<div><h2>${esc(selected.name)}</h2><small class="muted">@${esc(selected.username)}</small></div><div class="conversation-tools"><label>Fondo<select class="select chat-bg" data-key="${conversationKey}"><option value="gradient">Aurora</option><option value="solid">Azul profundo</option><option value="lavender">Lavanda</option><option value="warm">Negro cálido</option><option value="custom">Foto subida</option></select></label><label class="background-upload">Foto<input class="input chat-bg-upload" type="file" accept="image/png,image/jpeg,image/webp" data-key="${conversationKey}"></label><button class="btn secondary call-user" data-id="${selected.id}" data-video="false">Llamar</button><button class="btn secondary call-user" data-id="${selected.id}" data-video="true">Video</button></div>`:'<h2>Selecciona una conversación</h2>'}</div><div class="message-list" style="background:${chatBackground(conversationKey)}">${messages.map(message=>`<article class="message ${message.sender_id===state.user.id?'mine':''}">${avatarMarkup({name:message.sender_name,profile_photo:message.sender_photo},'message-avatar')}<div><p>${esc(message.content)}</p><small>${new Date(message.created_at).toLocaleString('es')}</small></div></article>`).join('')||'<div class="empty">No hay mensajes todavía.</div>'}</div>${selected?`<form id="message-form" class="message-form"><textarea class="textarea" name="content" rows="2" placeholder="Escribe un mensaje..." required></textarea><button class="btn">Enviar</button></form>`:''}</section></section><div id="call-modal" class="call-modal" hidden><div class="call-panel"><div class="call-head"><strong>Llamada</strong><button class="btn danger" id="hangup">Colgar</button></div><video id="call-remote" autoplay playsinline></video><video id="call-local" autoplay muted playsinline></video></div></div>`}
async function renderMessages(){signalSocket();const selectedId=new URLSearchParams(location.hash.split('?')[1]||'').get('user');layout(await messagesView(selectedId));document.querySelectorAll('.conversation-user').forEach(button=>button.onclick=()=>{location.hash=`#/${state.user.role}/messages?user=${button.dataset.id}`;renderMessages()});document.querySelectorAll('.call-user').forEach(button=>button.onclick=()=>startCall(button.dataset.id,button.dataset.video==='true'));document.querySelector('#hangup')?.addEventListener('click',endCall);const background=document.querySelector('.chat-bg');const upload=document.querySelector('.chat-bg-upload');if(background){const key=background.dataset.key;const value=chatBackground(key);background.value=value.startsWith('/uploads/')?'custom':value.includes('C4B5')?'lavender':value.includes('201B19')?'warm':value.includes('#13202B,#2A3541')?'gradient':'solid';background.onchange=()=>{const backgrounds={gradient:'linear-gradient(135deg,#13202B,#2A3541)',solid:'#2A3541',lavender:'linear-gradient(135deg,#767E99,#C4B5C8)',warm:'linear-gradient(135deg,#201B19,#13202B)'};if(backgrounds[background.value]){localStorage.setItem(`haitani-chat-bg-${key}`,backgrounds[background.value]);renderMessages()}}}upload?.addEventListener('change',async()=>{if(!upload.files[0])return;try{const form=new FormData();form.append('background',upload.files[0]);const result=await api('/chat-backgrounds',{method:'POST',body:form});localStorage.setItem(`haitani-chat-bg-${upload.dataset.key}`,`url(${result.url}) center/cover no-repeat`);renderMessages()}catch(error){notify(error.message)}});document.querySelector('#message-form')?.addEventListener('submit',async event=>{event.preventDefault();const content=new FormData(event.target).get('content');try{await api('/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:selectedId,content})});renderMessages()}catch(error){notify(error.message)}})}
async function gantt(){
  const allTasks=await api('/tasks');
  const users=state.user.role==='admin'?await api('/users'):[];
  const today=new Date();today.setHours(0,0,0,0);
  const fallbackStart=new Date(today);
  const fallbackEnd=new Date(today);fallbackEnd.setDate(fallbackEnd.getDate()+14);
  const dates=allTasks.flatMap(t=>[t.start_date&&new Date(`${t.start_date}T00:00:00`),t.due_date&&new Date(`${t.due_date}T00:00:00`)]).filter(Boolean);
  const rangeStart=new Date(Math.min(...dates.map(date=>date.getTime()),fallbackStart.getTime()));
  const rangeEnd=new Date(Math.max(...dates.map(date=>date.getTime()),fallbackEnd.getTime()));
  const dayMs=86400000;
  const totalDays=Math.max(1,Math.round((rangeEnd-rangeStart)/dayMs)+1);
  const cfg=GANTT_ZOOM[ganttZoom];
  const dayLabels=Array.from({length:totalDays},(_,index)=>{const date=new Date(rangeStart.getTime()+index*dayMs);const show=cfg.labelEvery==='month'?(date.getDate()===1||index===0):index%cfg.labelEvery===0;if(!show)return '';return `<span style="grid-column:${index+1}">${cfg.format(date)}</span>`}).join('');
  const todayOffset=Math.round((today-rangeStart)/dayMs);
  const progress={pendiente:0,en_proceso:50,completada:100};
  const tasks=allTasks.filter(t=>(!ganttStatusFilter||t.status===ganttStatusFilter)&&(!ganttAssigneeFilter||String(t.assigned_to||'')===ganttAssigneeFilter));
  const barHtml=task=>{const start=task.start_date?new Date(`${task.start_date}T00:00:00`):rangeStart;const end=task.due_date?new Date(`${task.due_date}T00:00:00`):start;const offset=Math.max(0,Math.round((start-rangeStart)/dayMs));const duration=Math.max(1,Math.round((end-start)/dayMs)+1);const percent=progress[task.status]??0;const marker=(todayOffset>=offset&&todayOffset<offset+duration)?`<i class="gantt-today-marker" style="left:${((todayOffset-offset)/duration*100)}%"></i>`:'';return `<div class="gantt-row"><div class="gantt-label"><strong>${esc(task.title)}</strong><small class="muted">${esc(task.assignee_name||'Sin asignar')}</small><small class="muted">${esc(task.start_date||'Sin inicio')} · ${esc(task.due_date||'Sin vencimiento')}</small></div><div class="gantt-track" style="--offset:${offset};--duration:${duration};--days:${totalDays};--gantt-col:${cfg.colWidth}px" data-id="${task.id}" data-start="${task.start_date||''}" data-due="${task.due_date||''}" data-total-days="${totalDays}">${marker}<div class="gantt-bar ${task.status}" style="--progress:${percent}%"><span class="resize-handle left" data-side="left" data-id="${task.id}"></span><span class="bar-body" data-id="${task.id}">${percent}%</span><span class="resize-handle right" data-side="right" data-id="${task.id}"></span></div></div><strong class="gantt-percent">${percent}%</strong></div>`};
  const groups=new Map();
  if(ganttGroupBy==='assignee'){tasks.forEach(t=>{const key=t.assignee_name||'Sin asignar';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t)})}else{groups.set('',tasks)}
  const groupsHtml=[...groups.entries()].map(([key,groupTasks])=>{if(!key)return groupTasks.map(barHtml).join('');const collapsed=ganttCollapsedGroups.has(key);return `<div class="gantt-group"><button class="gantt-group-head" data-toggle-group="${esc(key)}">${collapsed?'▸':'▾'} ${esc(key)} <span class="muted">(${groupTasks.length})</span></button>${collapsed?'':groupTasks.map(barHtml).join('')}</div>`}).join('')||'<div class="empty">No hay tareas para mostrar.</div>';
  const bodyWidth=totalDays*cfg.colWidth+320;
  const zoomButtons=['day','week','month'].map(z=>`<button class="btn secondary gantt-zoom ${ganttZoom===z?'active':''}" data-zoom="${z}">${z==='day'?'Día':z==='week'?'Semana':'Mes'}</button>`).join('');
  const assigneeOptions=users.filter(u=>u.role==='member').map(u=>`<option value="${u.id}" ${ganttAssigneeFilter===String(u.id)?'selected':''}>${esc(u.name)}</option>`).join('');
  return `${heading('Gantt','Arrastra una barra para mover sus fechas, o sus extremos para ajustar la duración.')}<section class="card gantt-card"><div class="gantt-controls"><div class="actions"><span class="muted gantt-controls-label">Zoom</span>${zoomButtons}</div><div class="actions"><label class="inline"><span class="muted gantt-controls-label">Agrupar</span><select class="select" id="gantt-group"><option value="none" ${ganttGroupBy==='none'?'selected':''}>Sin agrupar</option><option value="assignee" ${ganttGroupBy==='assignee'?'selected':''}>Por integrante</option></select></label><label class="inline"><span class="muted gantt-controls-label">Estado</span><select class="select" id="gantt-status-filter"><option value="">Todos</option><option value="pendiente" ${ganttStatusFilter==='pendiente'?'selected':''}>Pendiente</option><option value="en_proceso" ${ganttStatusFilter==='en_proceso'?'selected':''}>En proceso</option><option value="completada" ${ganttStatusFilter==='completada'?'selected':''}>Completada</option></select></label>${assigneeOptions?`<label class="inline"><span class="muted gantt-controls-label">Integrante</span><select class="select" id="gantt-assignee-filter"><option value="">Todos</option>${assigneeOptions}</select></label>`:''}<button class="btn secondary" id="gantt-today-btn">Hoy</button></div></div><div class="gantt-scroll"><div class="gantt-body" style="min-width:${bodyWidth}px"><div class="gantt-calendar"><div class="gantt-calendar-label">Calendario</div><div class="gantt-days" style="--days:${totalDays};--gantt-col:${cfg.colWidth}px">${dayLabels}</div></div><div class="gantt-list">${groupsHtml}</div></div></div><div class="gantt-legend"><span><i class="gantt-dot pendiente"></i>Pendiente 0%</span><span><i class="gantt-dot en_proceso"></i>En proceso 50%</span><span><i class="gantt-dot completada"></i>Completada 100%</span></div></section>`
}
async function renderGantt(){layout(await gantt());bindGanttEvents()}
function bindGanttEvents(){
  document.querySelectorAll('.gantt-zoom').forEach(btn=>btn.onclick=()=>{ganttZoom=btn.dataset.zoom;renderGantt()});
  document.querySelector('#gantt-group')?.addEventListener('change',e=>{ganttGroupBy=e.target.value;renderGantt()});
  document.querySelector('#gantt-status-filter')?.addEventListener('change',e=>{ganttStatusFilter=e.target.value;renderGantt()});
  document.querySelector('#gantt-assignee-filter')?.addEventListener('change',e=>{ganttAssigneeFilter=e.target.value;renderGantt()});
  document.querySelectorAll('[data-toggle-group]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.toggleGroup;ganttCollapsedGroups.has(key)?ganttCollapsedGroups.delete(key):ganttCollapsedGroups.add(key);renderGantt()});
  document.querySelector('#gantt-today-btn')?.addEventListener('click',()=>{const scrollEl=document.querySelector('.gantt-scroll');const marker=document.querySelector('.gantt-today-marker');if(scrollEl&&marker){const rect=marker.getBoundingClientRect();const scrollRect=scrollEl.getBoundingClientRect();scrollEl.scrollLeft+=(rect.left-scrollRect.left)-scrollRect.width/2}});
  document.querySelectorAll('.bar-body').forEach(handle=>handle.addEventListener('pointerdown',e=>startGanttDrag(e,'move')));
  document.querySelectorAll('.resize-handle').forEach(handle=>handle.addEventListener('pointerdown',e=>{e.stopPropagation();startGanttDrag(e,handle.dataset.side==='left'?'resize-left':'resize-right')}))
}
function startGanttDrag(event,mode){
  event.preventDefault();
  const id=event.currentTarget.dataset.id;
  const track=document.querySelector(`.gantt-track[data-id="${id}"]`);
  const bar=track?.querySelector('.gantt-bar');
  if(!track||!bar)return;
  const totalDays=Number(track.dataset.totalDays||1);
  const dayWidth=track.getBoundingClientRect().width/totalDays;
  const startX=event.clientX;
  const originalStart=track.dataset.start;
  const originalDue=track.dataset.due;
  let dragged=false;
  const onMove=moveEvent=>{const deltaDays=Math.round((moveEvent.clientX-startX)/dayWidth);if(deltaDays!==0)dragged=true;bar.style.transform=mode==='move'?`translateX(${deltaDays*dayWidth}px)`:'none'};
  const onUp=async moveEvent=>{
    document.removeEventListener('pointermove',onMove);
    bar.style.transform='';
    const deltaDays=Math.round((moveEvent.clientX-startX)/dayWidth);
    if(!dragged||deltaDays===0){if(mode==='move')openGanttQuickEdit(id);return}
    let newStart=originalStart,newDue=originalDue;
    if(mode==='move'){newStart=addDays(originalStart,deltaDays);newDue=addDays(originalDue,deltaDays)}
    else if(mode==='resize-right'){newDue=addDays(originalDue,deltaDays);if(new Date(newDue)<new Date(newStart))newDue=newStart}
    else if(mode==='resize-left'){newStart=addDays(originalStart,deltaDays);if(new Date(newStart)>new Date(newDue))newStart=newDue}
    try{const task=await api(`/tasks/${id}`);await api(`/tasks/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:task.title,description:task.description||'',assigned_to:task.assigned_to||'',priority:task.priority,status:task.status,start_date:newStart,due_date:newDue})});notify('Fechas actualizadas')}catch(error){notify(error.message)}
    renderGantt()
  };
  document.addEventListener('pointermove',onMove);
  document.addEventListener('pointerup',onUp,{once:true})
}
async function openGanttQuickEdit(id){
  let task;try{task=await api(`/tasks/${id}`)}catch(error){notify(error.message);return}
  document.querySelectorAll('.gantt-popover').forEach(node=>node.remove());
  const popover=document.createElement('div');
  popover.className='gantt-popover';
  popover.innerHTML=`<strong>${esc(task.title)}</strong><label>Estado<select class="select" id="gp-status"><option value="pendiente" ${task.status==='pendiente'?'selected':''}>Pendiente</option><option value="en_proceso" ${task.status==='en_proceso'?'selected':''}>En proceso</option><option value="completada" ${task.status==='completada'?'selected':''}>Completada</option></select></label><div class="actions"><button class="btn" id="gp-save">Guardar</button><button type="button" class="btn secondary" id="gp-close">Cerrar</button></div>`;
  document.body.append(popover);
  const bar=document.querySelector(`.gantt-track[data-id="${id}"] .gantt-bar`);
  const rect=bar.getBoundingClientRect();
  popover.style.left=`${Math.min(rect.left,window.innerWidth-260)}px`;
  popover.style.top=`${rect.bottom+8}px`;
  const close=()=>{popover.remove();document.removeEventListener('pointerdown',onOutside)};
  const onOutside=e=>{if(!popover.contains(e.target))close()};
  setTimeout(()=>document.addEventListener('pointerdown',onOutside),0);
  document.querySelector('#gp-close').onclick=close;
  document.querySelector('#gp-save').onclick=async()=>{try{await api(`/tasks/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:task.title,description:task.description||'',assigned_to:task.assigned_to||'',priority:task.priority,status:document.querySelector('#gp-status').value,start_date:task.start_date||'',due_date:task.due_date||''})});notify('Tarea actualizada');close();renderGantt()}catch(error){notify(error.message)}}
}
const renderMessagesLegacy=renderMessages;
renderMessages=async function(){await renderMessagesLegacy();const callHead=document.querySelector('.call-head');if(callHead&&!document.querySelector('#mute-call'))callHead.insertAdjacentHTML('beforeend','<button class="btn secondary" id="mute-call">Silenciar micrófono</button>');document.querySelector('#mute-call')?.addEventListener('click',toggleMute);const calls=await api('/calls').catch(()=>[]);if(calls.length&&!document.querySelector('.missed-calls')){const node=document.createElement('section');node.className='missed-calls';node.innerHTML=`<h2>Llamadas perdidas</h2>${calls.map(call=>`<div class="missed-call">${avatarMarkup({name:call.caller_name,profile_photo:call.caller_photo},'message-avatar')}<span><strong>${esc(call.caller_name)}</strong><small>${call.call_type==='video'?'Videollamada':'Llamada'} · ${new Date(call.created_at).toLocaleString('es')}</small></span></div>`).join('')}`;document.querySelector('.conversation-list')?.prepend(node)}}
async function settings(){return `${heading('Configuración','El token solo vive en memoria del servidor y nunca se devuelve al navegador.')}<section class="card"><form id="github-settings" class="form-grid"><label>URL del repositorio<input class="input" name="url" placeholder="https://github.com/owner/repository" required></label><label>Owner<input class="input" name="owner" required></label><label>Repository<input class="input" name="repo" placeholder="CoffeeKorea" required></label><label>Token de GitHub<input class="input" name="token" type="password" required></label><div class="actions full"><button class="btn">Guardar y probar conexión</button></div></form></section>`}
async function renderSettings(){layout(await settings());document.querySelector('#github-settings').onsubmit=async e=>{e.preventDefault();try{await api('/github/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await api('/github/test');notify('Conexión con GitHub establecida correctamente.')}catch(error){notify(error.message)}}}
async function enhanceConversation(){const conversation=document.querySelector('.conversation');if(!conversation||conversation.dataset.enhanced)return;conversation.dataset.enhanced='true';const selectedId=new URLSearchParams(location.hash.split('?')[1]||'').get('user');if(!selectedId)return;const key=`${Math.min(state.user.id,Number(selectedId))}-${Math.max(state.user.id,Number(selectedId))}`;const header=conversation.querySelector('.conversation-header');header?.insertAdjacentHTML('beforeend','<div class="conversation-actions"><button class="btn secondary" id="archive-conversation">Archivar</button><button class="btn danger" id="delete-conversation">Borrar</button><button class="btn secondary" id="schedule-call">Programar llamada</button></div>');const messages=await api(`/messages?user_id=${selectedId}`).catch(()=>[]);document.querySelectorAll('.message.mine small').forEach((node,index)=>{const message=messages.filter(item=>item.sender_id===state.user.id)[index];if(message)node.textContent=`${node.textContent} · ${message.delivery_status==='leido'?'✓✓ leído':message.delivery_status==='entregado'?'✓✓ entregado':'✓ enviado'}`});document.querySelector('#archive-conversation').onclick=()=>{localStorage.setItem(`haitani-archived-${key}`,'1');notify('Conversación archivada')};document.querySelector('#delete-conversation').onclick=async()=>{if(confirm('¿Borrar toda esta conversación?')){await api(`/messages/conversation/${selectedId}`,{method:'DELETE'});renderMessages()}};document.querySelector('#schedule-call').onclick=async()=>{const date=prompt('Fecha y hora de la llamada (YYYY-MM-DDTHH:mm):');if(!date)return;try{await api('/calls',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({receiver_id:selectedId,call_type:'audio',scheduled_at:date})});notify('Llamada programada');}catch(error){notify(error.message)}}}
const conversationObserver=new MutationObserver(()=>enhanceConversation());conversationObserver.observe(app,{childList:true,subtree:true});
async function render(){if(!state.user){try{state.user=(await api('/auth/me')).user}catch{}if(!state.user)return loginView()}await refreshNotifications();startNotificationPolling();const route=location.hash||`#/${state.user.role}/dashboard`;try{if(route.includes('kanban'))return renderKanban();if(route.includes('gantt'))return renderGantt();if(route.includes('messages'))return renderMessages();if(route.includes('members'))return state.user.role==='admin'?renderMembers():renderTeam();if(route.includes('files'))return renderFiles();if(route.includes('settings'))return renderSettings();if(route.includes('profile'))return renderProfile();if(route.includes('team-activity'))return renderGithub('activity');if(route.includes('github'))return renderGithub(route.includes('commits')?'commits':route.includes('branches')?'branches':route.includes('pull-requests')?'pulls':route.includes('activity')?'activity':'repository');if(route.includes('tasks'))return renderTasks();return renderDashboard()}catch(error){layout(`<div class="alert">${esc(error.message)}</div>`)}}
window.addEventListener('hashchange',render);render();